class IncrementalCSE:
    """
    Stateful common subexpression elimination for a growing constraint set.

    Symbolic execution appends one path constraint at a time, and forked states
    share most of their prefix. A one-shot :meth:`simplify_constraints` pass
    therefore misses duplicates spread across many successive additions. This
    class keeps the substitution table built so far and applies it to every new
    constraint, while promoting newly seen, frequently recurring compound
    subexpressions to named symbols.

    The transformation is equivalence preserving: each symbol is bound by an
    equality constraint emitted the first time it is introduced.
    """

    def __init__(self, strategy: ConstraintSimplificationStrategy | None = None, min_depth: int = 3):
        self.strategy = _default_strategy if strategy is None else strategy
        self.min_depth = min_depth
        self._substitutions: dict[int, tuple[claripy.ast.Base, claripy.ast.Base]] = {}
        self._occurrences: collections.Counter[int] = collections.Counter()
        self._expr_by_hash: dict[int, claripy.ast.Base] = {}
        self._symbol_counter = 0

    def _apply_substitutions(self, expr: claripy.ast.Base) -> claripy.ast.Base:
        result = expr
        for shared_hash, (shared, symbol) in self._substitutions.items():
            if shared_hash == hash(result):
                return symbol
            if self._mentions(result, shared_hash):
                result = claripy.replace(result, shared, symbol)
        return result

    @staticmethod
    def _mentions(node: claripy.ast.Base, target_hash: int) -> bool:
        if not isinstance(node, claripy.ast.Base):
            return False
        if hash(node) == target_hash:
            return True
        return any(IncrementalCSE._mentions(child, target_hash) for child in node.args)

    def _record(self, node: claripy.ast.Base) -> None:
        if not isinstance(node, claripy.ast.Base):
            return
        if isinstance(node, claripy.ast.Bool):
            return
        node_hash = hash(node)
        self._occurrences[node_hash] += 1
        self._expr_by_hash.setdefault(node_hash, node)
        for child in node.args:
            self._record(child)

    def add(self, constraint: claripy.ast.Base) -> list[claripy.ast.Base]:
        """
        Rewrite one incoming constraint against the accumulated substitution
        table, returning the constraints to actually store (usually one, plus a
        definition when a new shared symbol is introduced).
        """
        simplified = self.strategy.simplify_constraint(constraint)
        rewritten = self._apply_substitutions(simplified)

        # Record subexpressions of the original (pre-substitution) expression so
        # recurring structures across forked-path constraints are detected.
        self._record(simplified)

        new_definitions: list[claripy.ast.Base] = []
        recurring = [
            self._expr_by_hash[node_hash]
            for node_hash, count in self._occurrences.items()
            if count >= 2
            and node_hash not in self._substitutions
            and self._expr_by_hash[node_hash].depth >= self.min_depth
        ]
        # Promote the deepest recurring expressions first; skip those contained
        # in an already-selected larger one.
        recurring.sort(key=lambda e: e.depth, reverse=True)
        for shared in recurring:
            if any(
                self._mentions(selected, hash(shared))
                for selected, _ in self._substitutions.values()
            ):
                continue
            symbol = claripy.BVS(f"cse_{self._symbol_counter}", shared.length)
            self._symbol_counter += 1
            self._substitutions[hash(shared)] = (shared, symbol)
            new_definitions.append(symbol == shared)
            rewritten = claripy.replace(rewritten, shared, symbol)

        out = [rewritten]
        for definition in new_definitions:
            out.append(self._apply_substitutions(definition))
        return out

